package fixture;import java.util.*;import net.minecraft.nbt.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;public class Entity{public UUID uuid=UUID.randomUUID();public int id=uuid.hashCode(),hurtTime;public double x,y,z;public float hp=20,max=20;public boolean alive=true,visible=true,shift;public int messages;public List<Object> chat=new ArrayList<>();public World w;public CompoundTag tag=new CompoundTag();public List<ItemStack> bag=new ArrayList<>();public EnumMap<EquipmentSlot,ItemStack> equipment=new EnumMap<>(EquipmentSlot.class);public Object target,lastAttacker;public Nav navigation=new Nav();public Entity(World w){this.w=w;w.entities.add(this);for(EquipmentSlot s:EquipmentSlot.values())equipment.put(s,ItemStack.EMPTY);}public UUID getUUID(){return uuid;}public int getId(){return id;}public void setPos(double x,double y,double z){this.x=x;this.y=y;this.z=z;}public float getHealth(){return hp;}public float getMaxHealth(){return max;}public boolean noAi;public Object pose;public void setHealth(float n){hp=n;}public void setNoAi(boolean v){noAi=v;}public float getYRot(){return head;}public void setYRot(float v){head=v;}public net.minecraft.core.BlockPos blockPosition(){return new net.minecraft.core.BlockPos((int)x,(int)y,(int)z);}public Sources damageSources(){return new Sources();}public static class Sources{public Damage genericKill(){return new Damage("genericKill");}}public static class Damage{String id;public Damage(String id){this.id=id;}public String getMsgId(){return id;}}public void die(Object source){alive=false;}public void heal(float n){hp=Math.min(max,hp+n);}public boolean isAlive(){return alive;}public void setPersistenceRequired(){}public World level(){return w;}public Server getServer(){return w.server;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public net.minecraft.world.phys.Vec3 getEyePosition(){return new net.minecraft.world.phys.Vec3(x,y+1.6,z);}public float getBbHeight(){return 1.8f;}public CompoundTag getPersistentData(){return tag;}public Box getBoundingBox(){return new Box(x,y,z,0);}public Entity getSensing(){return this;}public boolean hasLineOfSight(Object n){return visible&&((Entity)n).visible;}public Entity getLookControl(){return this;}public void setLookAt(Object target,float a,float b){}public Nav getNavigation(){return navigation;}public double distanceToSqr(Entity n){return (x-n.x)*(x-n.x)+(y-n.y)*(y-n.y)+(z-n.z)*(z-n.z);}public ItemStack getMainHandItem(){return equipment.get(EquipmentSlot.MAINHAND);}public ItemStack getOffhandItem(){return equipment.get(EquipmentSlot.OFFHAND);}public ItemStack getItemInHand(InteractionHand h){return h==InteractionHand.MAIN_HAND?getMainHandItem():getOffhandItem();}public ItemStack getItemBySlot(EquipmentSlot s){return equipment.get(s);}public void setItemSlot(EquipmentSlot s,ItemStack i){equipment.put(s,i);}public void setTarget(Object n){target=n;}public Object getLastHurtByMob(){return lastAttacker;}public void aim(boolean a){}public void setAggressive(boolean a){}public void setShiftKeyDown(boolean b){shift=b;}public boolean isShiftKeyDown(){return shift;}public Synced synced=new Synced();public Object getEntityData(){return synced;}public static class Synced{public Object value;public void set(Object key,Object value){this.value=value;}}public Object customName;public float pitch,head;public int swings;public void setCustomName(Object n){customName=n;}public float getXRot(){return pitch;}public float getYHeadRot(){return head;}public void setXRot(float n){pitch=n;}public void setYHeadRot(float n){head=n;}public void setPose(Object p){pose=p;}public void swing(Object h){swings++;}public void spawnAtLocation(Object stack){w.dropped++;}public Name getDisplayName(){return new Name();}public static class Name{public String getString(){return "Test survivor";}}}